import express from "express";
import * as transController from "../controllers/TransController.js";
import { authenticateToken } from "../middlewares/auth.js";

const router = express.Router();

// Follow main-backend standards: protect endpoints with authenticateToken where appropriate
router.use(authenticateToken);

router.get("/menu", transController.getMenu);
router.get("/resourceTypes", transController.getResourceTypes);

router.get("/resources/:pageId", transController.getPageResources);
router.get("/resources/page/:lang/translation", (req, res, next) => {
  req.params.pageId = 0;
  next();
}, transController.getPageResources);
router.get("/resources/page/:lang/:pageId", transController.getPageResources);
router.get("/resources/page/:pageId", transController.getPageResourcesWithoutGrouping);

router.get("/pages", transController.getPages); // returns list of pages
router.get("/groups", transController.getGroups); // returns groups
router.get("/authPermissions/:resourceId", transController.getAuthPermissions);

router.get("/resources", transController.newGetAllResources);
router.get("/resource/:resourceId", transController.getResource);

router.post("/resources", transController.addLocalizedResource);
router.put("/resource", transController.updateResourceController);
router.delete("/resource/:resourceId", transController.deleteResourceController);

router.post("/resources/batch", transController.addLocalizedResourcesBatch);

export default router;
